			}
			assertNotNull("index.json has no layer " + r.getLayer(), l);
			assertTrue(r.getCode() + " " + r.getName() + " outside " + l.getId(), l.contains(r.getX() + 0.5, r.getY() + 0.5));
		}
		for (Portal p : repo.getPortals())
		{
